// Autoverificação do protótipo; não substitui testes da aplicação.
const { chromium } = require('@playwright/test')
const assert = require('node:assert/strict')
const path = require('node:path')
const { pathToFileURL } = require('node:url')
const fs = require('node:fs')
const output = path.resolve(process.argv[2] || __dirname)
async function main() {
  const executablePath = process.env.PROTOTYPE_BROWSER
  const browser = await chromium.launch({ headless: true, ...(executablePath ? { executablePath } : {}) })
  try {
    const page = await browser.newPage({ viewport: { width: 1440, height: 980 } })
    const errors = []
    page.on('pageerror', error => errors.push(error.message))
    const requests = []
    page.on('request', request => { if (/^https?:/.test(request.url())) requests.push(request.url()) })
    await page.goto(pathToFileURL(path.join(output, 'index.html')).href)
    await page.evaluate(() => document.fonts.ready)
    assert.equal(await page.locator('#tabs [role=tab]').count(), 4)
    await page.screenshot({ path: path.join(output, 'monitoramento-desktop.png'), fullPage: true })
    await page.getByRole('button', { name: 'Pausar coleta', exact: true }).click()
    const dialog = page.getByRole('dialog')
    await dialog.locator('textarea').fill('Manutenção programada')
    await dialog.getByRole('checkbox').check()
    await dialog.getByRole('button', { name: 'Confirmar pausa', exact: true }).click()
    assert.match(await page.locator('#dialog-error').textContent(), /Nenhuma alteração/)
    assert.equal(await dialog.locator('textarea').inputValue(), 'Manutenção programada')
    await dialog.getByRole('checkbox').uncheck()
    await dialog.getByRole('button', { name: 'Confirmar pausa', exact: true }).click()
    assert.match(await page.locator('#panel').textContent(), /Coleta pausada/)
    await page.getByRole('button', { name: 'Alternar tema' }).click()
    await page.screenshot({ path: path.join(output, 'monitoramento-pausado-escuro.png'), fullPage: true })
    await page.getByRole('button', { name: 'Alternar tema' }).click()
    await page.getByRole('tab', { name: 'Usuários', exact: true }).click()
    await page.getByRole('searchbox').fill('PAULO')
    assert.equal(await page.locator('tbody tr').count(), 1)
    await page.getByRole('button', { name: 'Limpar filtros', exact: true }).click()
    await page.getByRole('button', { name: 'Gerenciar Camila Souza', exact: true }).click()
    await dialog.locator('[name=operation]').selectOption('Bloqueada')
    await dialog.locator('textarea').fill('Revisão de acesso')
    await dialog.getByRole('button', { name: 'Revisar alteração', exact: true }).click()
    assert.match(await dialog.textContent(), /Ativa → Bloqueada/)
    await dialog.getByRole('button', { name: 'Confirmar alteração', exact: true }).click()
    assert.match(await page.locator('tbody tr').first().textContent(), /Bloqueada/)
    await page.screenshot({ path: path.join(output, 'usuarios-desktop.png'), fullPage: true })
    await page.locator('#size').selectOption('all')
    assert.equal(await page.locator('tbody tr').count(), 3)
    await page.getByRole('button', { name: 'Criar conta', exact: true }).click()
    await dialog.locator('[name=name]').fill('São Paulo Operações')
    await dialog.locator('[name=email]').fill('operacoes@example.org')
    await dialog.getByRole('button', { name: 'Criar conta', exact: true }).click()
    await page.getByRole('searchbox').fill('sao')
    assert.match(await page.locator('tbody').textContent(), /São Paulo Operações/)
    await page.getByRole('tab', { name: 'Auditoria', exact: true }).click()
    await page.getByRole('button', { name: 'Abrir evento' }).first().click()
    assert.match(await dialog.textContent(), /Antes/)
    assert.match(await dialog.textContent(), /Depois/)
    await page.keyboard.press('Escape')
    assert.equal(await dialog.isVisible(), false)
    await page.screenshot({ path: path.join(output, 'auditoria-desktop.png'), fullPage: true })
    await page.locator('#role').selectOption('Analista')
    assert.equal(await page.locator('#tabs [role=tab]').count(), 1)
    assert.match(await page.locator('#panel').textContent(), /Metodologia e minhas preferências/)
    assert.equal(await page.getByRole('button', { name: 'Criar conta', exact: true }).count(), 0)
    await page.screenshot({ path: path.join(output, 'conta-pessoal-desktop.png'), fullPage: true })
    await page.locator('#state').selectOption('denied')
    assert.match(await page.locator('#panel').textContent(), /Acesso restrito/)
    await page.getByRole('button', { name: 'Ir para minha conta', exact: true }).click()
    await page.locator('#role').selectOption('Admin')
    await page.getByRole('tab', { name: 'Monitoramento', exact: true }).click()
    await page.getByRole('button', { name: 'Retomar coleta', exact: true }).click()
    await dialog.locator('textarea').fill('Manutenção concluída')
    await dialog.getByRole('button', { name: 'Confirmar retomada', exact: true }).click()
    await page.setViewportSize({ width: 390, height: 844 })
    assert.equal(await page.evaluate(() => document.documentElement.scrollWidth <= innerWidth), true)
    await page.screenshot({ path: path.join(output, 'monitoramento-mobile.png'), fullPage: true })
    await page.locator('#area').selectOption('users')
    assert.equal(await page.evaluate(() => document.documentElement.scrollWidth <= innerWidth), true)
    await page.screenshot({ path: path.join(output, 'usuarios-mobile.png'), fullPage: true })
    await page.locator('#role').selectOption('Visitante')
    assert.equal(await page.locator('#area option').count(), 1)
    await page.screenshot({ path: path.join(output, 'conta-pessoal-mobile.png'), fullPage: true })
    assert.deepEqual(errors, [])
    assert.deepEqual(requests, [])
    fs.writeFileSync(path.join(output, 'verificacao.json'), JSON.stringify({ passed: true, screenshots: 8, browser: await browser.version(), apiRequests: requests.length, pageErrors: errors.length, note: 'Protótipo local; não valida implementação ou importação Figma' }, null, 2))
    console.log('Protótipo validado: papéis, confirmação, falha/retry, busca, acentos, criação, auditoria e mobile; 8 capturas; nenhuma chamada HTTP.')
  } finally {
    await browser.close()
  }
}
main().catch(error => { console.error(error); process.exitCode = 1 })
